content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body, html, #root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: #05050a;
  color: #ffffff;
}

.solar-app {
  position: relative;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
}

.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.ui-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 2;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 20px;
}

.ui-overlay > * {
  pointer-events: auto;
}

.title {
  font-size: 1.8rem;
  font-weight: 700;
  letter-spacing: 2px;
  color: #ffffff;
  text-shadow: 0 0 10px rgba(255, 255, 255, 0.5);
  margin-bottom: 5px;
}

.control-panel {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  background: rgba(15, 15, 30, 0.7);
  padding: 15px;
  border-radius: 12px;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37);
  max-width: 600px;
  will-change: backdrop-filter;
}

.btn {
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #ffffff;
  padding: 8px 16px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 0.9rem;
  transition: all 0.3s ease;
  user-select: none;
}

.btn:hover {
  background: rgba(255, 255, 255, 0.25);
  border-color: rgba(255, 255, 255, 0.4);
}

.btn:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

.btn-active {
  background: #3b82f6;
  border-color: #60a5fa;
  box-shadow: 0 0 10px rgba(59, 130, 246, 0.5);
}

.info-panel {
  position: absolute;
  top: 20px;
  right: 20px;
  width: 320px;
  background: rgba(15, 15, 30, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
  z-index: 10;
  animation: fadeIn 0.3s ease-out forwards;
  will-change: opacity, transform, backdrop-filter;
}

.planet-title {
  font-size: 1.5rem;
  font-weight: 600;
  margin-bottom: 12px;
  color: #f3f4f6;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  padding-bottom: 8px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.planet-desc {
  font-size: 0.95rem;
  line-height: 1.5;
  color: #d1d5db;
  margin-bottom: 15px;
}

.close-btn {
  background: transparent;
  border: none;
  color: #9ca3af;
  font-size: 1.2rem;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 4px;
  transition: color 0.2s, background 0.2s;
}

.close-btn:hover {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.1);
}

.close-btn:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 768px) {
  .ui-overlay {
    padding: 10px;
  }

  .info-panel {
    top: auto;
    bottom: 10px;
    right: 10px;
    left: 10px;
    width: auto;
  }

  .control-panel {
    max-width: 100%;
  }
}

export interface PlanetData {
  id: string;
  name: string;
  size: number;
  distance: number;
  speed: number;
  color: string;
  description: string;
  radiusText: string;
  distanceText: string;
  periodText: string;
}

import { FC } from 'react';
import { PlanetData } from '../types';

interface PlanetInfoProps {
  planet: PlanetData | null;
  onClose: () => void;
}

export const PlanetInfo: FC<PlanetInfoProps> = ({ planet, onClose }) => {
  if (!planet) return null;

  return (
    <div className="info-panel">
      <div className="planet-title">
        <span>{planet.name}</span>
        <button className="close-btn" onClick={onClose}>×</button>
      </div>
      <p className="planet-desc">{planet.description}</p>
      <div style={{ fontSize: '0.85rem', color: '#9ca3af', display: 'flex', flexDirection: 'column', gap: '6px' }}>
        <div>半径: {planet.radiusText}</div>
        <div>太陽からの距離: {planet.distanceText}</div>
        <div>公転周期: {planet.periodText}</div>
      </div>
    </div>
  );
};

export default PlanetInfo;

