export default function App() {
  const containerRef = useRef<HTMLDivElement>(null);
  const [selectedPlanet, setSelectedPlanet] = useState<PlanetData | null>(null);
  const [isRotating, setIsRotating] = useState<boolean>(true);
  const [showOrbits, setShowOrbits] = useState<boolean>(true);

  // Three.js instances ref
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const planetsMeshRef = useRef<{ [key: string]: THREE.Mesh }>({});
  const orbitsMeshRef = useRef<THREE.Line[]>([]);
  const anglesRef = useRef<{ [key: string]: number }>({});

  const isRotatingRef = useRef(isRotating);
  isRotatingRef.current = isRotating;

  const showOrbitsRef = useRef(showOrbits);
  showOrbitsRef.current = showOrbits;

  const selectPlanetHandler = useCallback((planet: PlanetData | null) => {
    setSelectedPlanet(planet);
  }, []);

  useEffect(() => {
    if (!containerRef.current) return;

    // Scene
    const scene = new THREE.Scene();
    sceneRef.current = scene;

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      1000
    );
    camera.position.set(0, 25, 45);
    camera.lookAt(0, 0, 0);
    cameraRef.current = camera;

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    containerRef.current.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    // Ambient Light
    const ambientLight = new THREE.AmbientLight(0x333333);
    scene.add(ambientLight);

    // Point Light (Sun)
    const sunLight = new THREE.PointLight(0xffffff, 2, 300);
    scene.add(sunLight);

    // Sun Mesh
    const sunGeometry = new THREE.SphereGeometry(3, 32, 32);
    const sunMaterial = new THREE.MeshBasicMaterial({ color: 0xffaa00 });
    const sunMesh = new THREE.Mesh(sunGeometry, sunMaterial);
    scene.add(sunMesh);

    // Planets & Orbits
    PLANETS_DATA.forEach((planet) => {
      anglesRef.current[planet.id] = Math.random() * Math.PI * 2;

      // Orbit Line
      const orbitPoints = [];
      const segments = 128;
      for (let i = 0; i <= segments; i++) {
        const theta = (i / segments) * Math.PI * 2;
        orbitPoints.push(
          new THREE.Vector3(
            Math.cos(theta) * planet.distance,
            0,
            Math.sin(theta) * planet.distance
          )
        );
      }
      const orbitGeometry = new THREE.BufferGeometry().setFromPoints(orbitPoints);
      const orbitMaterial = new THREE.LineBasicMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0.15
      });
      const orbitLine = new THREE.Line(orbitGeometry, orbitMaterial);
      scene.add(orbitLine);
      orbitsMeshRef.current.push(orbitLine);

      // Planet Mesh
      const planetGeometry = new THREE.SphereGeometry(planet.size, 32, 32);
      const planetMaterial = new THREE.MeshStandardMaterial({
        color: planet.color,
        roughness: 0.8
      });
      const planetMesh = new THREE.Mesh(planetGeometry, planetMaterial);
      planetMesh.userData = { id: planet.id };
      scene.add(planetMesh);
      planetsMeshRef.current[planet.id] = planetMesh;

      // Saturn Ring if saturn
      if (planet.id === 'saturn') {
        const ringGeometry = new THREE.RingGeometry(planet.size * 1.4, planet.size * 2.3, 32);
        const ringMaterial = new THREE.MeshBasicMaterial({
          color: 0xc2b280,
          side: THREE.DoubleSide,
          transparent: true,
          opacity: 0.7
        });
        const ringMesh = new THREE.Mesh(ringGeometry, ringMaterial);
        ringMesh.rotation.x = Math.PI / 2;
        planetMesh.add(ringMesh);
      }
    });

    // Raycaster for clicks
    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();

    const handlePointerDown = (event: PointerEvent) => {
      if (!rendererRef.current || !cameraRef.current || !sceneRef.current) return;
      const rect = rendererRef.current.domElement.getBoundingClientRect();
      mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
      mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;

      raycaster.setFromCamera(mouse, cameraRef.current);
      const meshes = Object.values(planetsMeshRef.current);
      const intersects = raycaster.intersectObjects(meshes);

      if (intersects.length > 0) {
        const hit = intersects[0].object as THREE.Mesh;
        const planetId = hit.userData.id;
        const found = PLANETS_DATA.find((p) => p.id === planetId);
        if (found) {
          selectPlanetHandler(found);
        }
      }
    };

    const domElement = renderer.domElement;
    domElement.addEventListener('pointerdown', handlePointerDown);

    // Resize handler
    const handleResize = () => {
      if (!cameraRef.current || !rendererRef.current) return;
      cameraRef.current.aspect = window.innerWidth / window.innerHeight;
      cameraRef.current.updateProjectionMatrix();
      rendererRef.current.setSize(window.innerWidth, window.innerHeight);
    };

    window.addEventListener('resize', handleResize);

    // Animation Loop
    let animationFrameId: number;
    const animate = () => {
      animationFrameId = requestAnimationFrame(animate);

      if (isRotatingRef.current) {
        PLANETS_DATA.forEach((planet) => {
          anglesRef.current[planet.id] += planet.speed * 0.5;
          const angle = anglesRef.current[planet.id];
          const mesh = planetsMeshRef.current[planet.id];
          if (mesh) {
            mesh.position.x = Math.cos(angle) * planet.distance;
            mesh.position.z = Math.sin(angle) * planet.distance;
            mesh.rotation.y += 0.01;
          }
        });
      }

      orbitsMeshRef.current.forEach((orbit) => {
        orbit.visible = showOrbitsRef.current;
      });

      if (rendererRef.current && sceneRef.current && cameraRef.current) {
        rendererRef.current.render(sceneRef.current, cameraRef.current);
      }
    };

    animate();

    return () => {
      domElement.removeEventListener('pointerdown', handlePointerDown);
      window.removeEventListener('resize', handleResize);
      cancelAnimationFrame(animationFrameId);
      if (rendererRef.current) {
        rendererRef.current.dispose();
        if (rendererRef.current.domElement && rendererRef.current.domElement.parentNode) {
          rendererRef.current.domElement.parentNode.removeChild(rendererRef.current.domElement);
        }
      }
    };
  }, [selectPlanetHandler]);

  return (
    <div className="solar-app">
      <div ref={containerRef} className="canvas-container" />

      <div className="ui-overlay">
        <div>
          <h1 className="title">太陽系 3D シミュレーション</h1>
          <div className="control-panel">
            <button
              className={`btn ${isRotating ? 'btn-active' : ''}`}
              onClick={() => setIsRotating(!isRotating)}
            >
              {isRotating ? '公転停止' : '公転再生'}
            </button>
            <button
              className={`btn ${showOrbits ? 'btn-active' : ''}`}
              onClick={() => setShowOrbits(!showOrbits)}
            >
              {showOrbits ? '軌道非表示' : '軌道表示'}
            </button>
          </div>
        </div>

        <PlanetInfo
          planet={selectedPlanet}
          onClose={() => setSelectedPlanet(null)}
        />
      </div>
    </div>
  );
}
